import { initial, available, apply, replay, encode, decode, score, brief } from './engine.mjs';
import { SAVE_KEY } from './limits.mjs';
import { campaign } from './content/mill-creek.mjs';
import { stages, routeStories, routePlan, stageProgress, outbound, bookLenses, assumptions } from './journey.mjs';
import { encounters, routeGroups } from './adventure.mjs';

const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'$'+n.toLocaleString('en-US');
const mascot=(className='')=>`<img class="scout ${className}" src="./game/assets/scout.webp" width="480" height="480" alt="Scout, your cheerful fox adventure guide">`;
const primary=(label,command,extra='')=>`<button class="button primary" data-command="${command}" ${extra}>${label}<span aria-hidden="true">➜</span></button>`;
let state=initial(campaign),goal='smaller',screen='launch',selected='control',routeId='smaller',groupId='develop',saved=false;
let outcome=null,previousScreen='travel',previousSelected='control',sound=false,audio=null,toastTimer=null,zoom=1,pan={x:0,y:0},drag=null;
try{const raw=localStorage.getItem(SAVE_KEY);if(raw){state=decode(campaign,raw);goal=state.ambition;routeId=goal;saved=true;}}catch{$('#save-notice').hidden=false;$('#save-notice').textContent='That saved adventure could not be loaded. You can start a fresh one.';}
const action=()=>campaign.actions.find(a=>a.id===selected);
const route=()=>campaign.routes.find(r=>r.id===routeId);
function save(){state={...state,ambition:goal};try{localStorage.setItem(SAVE_KEY,encode(state));saved=true;}catch{toast('Your device could not save this run. Keep this tab open or download your record.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function chime(celebrate=false){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();const notes=celebrate?[523,659,784]:[523,659];notes.forEach((hz,i)=>{const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.1;o.type='triangle';o.frequency.value=hz;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.055,t+.02);g.gain.exponentialRampToValueAtTime(.0001,t+.2);o.start(t);o.stop(t+.21);});}catch{sound=false;}}
function modal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;}
function close(){$('#modal').close();}
function show(next){screen=next;zoom=1;pan={x:0,y:0};render();const heading=$('#screen h1');heading?.setAttribute('tabindex','-1');heading?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function phase(){if(['directions','route','ending'].includes(screen))return 3;return action()?.phase??0;}
function stepTrail(n){return `<div class="step-trail" aria-label="Mission steps">${['Go','Decide','Discover'].map((label,i)=>`<span class="${i===n?'current':i<n?'passed':''}"><b>${i<n?'✓':i+1}</b>${label}</span>`).join('')}</div>`;}
function guideLine(text){return `<div class="guide-line">${mascot()}<div><span>SCOUT · YOUR FIELD GUIDE</span><p>${esc(text)}</p></div></div>`;}
function world({start=false}={}){
  const a=action(),last=state.done.length?campaign.actions.find(x=>x.id===state.done.at(-1)):null;
  const from=last?.marker??[83,83],to=a.marker;
  const marker=start?'':`<svg class="world-path" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path d="M${from[0]},${from[1]} Q${(from[0]+to[0])/2-10},${Math.min(from[1],to[1])-7} ${to[0]},${to[1]}"/></svg><div class="scout-token" style="left:${from[0]}%;top:${from[1]}%">${mascot()}<span>You are here</span></div><button class="destination" data-command="arrive" style="left:${to[0]}%;top:${to[1]}%" aria-label="Go to ${esc(encounters[a.id].place)}"><span>!</span><b>GO HERE</b></button>`;
  return `<div class="world-scene ${start?'start-world':''}"><div id="world-camera" class="world-camera"><img class="world-art" src="./game/assets/mill-creek.webp" width="1200" height="800" alt="Cartoon Mill Creek with a turquoise creek, bright meadow, woodland, and a small town along the road" draggable="false">${marker}</div><span class="world-label">MILL CREEK <i>22 acres of possibility</i></span>${!start?'<div class="world-controls"><button data-command="zoom-in" aria-label="Zoom in">+</button><button data-command="zoom-out" aria-label="Zoom out">−</button><button data-command="zoom-reset" aria-label="Reset map">⌖</button></div>':''}</div>`;
}
function render(){
  document.body.dataset.screen=screen;
  const active=screen!=='launch';$('#adventure-hud').hidden=!active;$('#guide-controls').hidden=!active||screen==='ending';
  $('#cash').textContent=money(state.cash);$('#time').textContent=state.deadline-state.day;$('#pack-count').textContent=state.done.length;
  $('#book-trail').innerHTML=stages.map((st,i)=>`<button data-stage="${i}" class="${phase()===i?'active':''} ${stageProgress(state,i).complete?'complete':''}" aria-current="${phase()===i?'step':'false'}"><span>${stageProgress(state,i).complete?'✦':'0'+(i+1)}</span><b>${st.name}</b></button>`).join('');
  const views={launch:launchView,travel:travelView,decision:decisionView,result:resultView,directions:directionsView,route:routeView,ending:endingView};
  $('#screen').innerHTML=views[screen]();
}
function launchView(){return `<section class="launch-page"><div class="launch-copy"><span class="eyebrow">THE BOOK BECOMES YOUR ADVENTURE</span><h1>Big ideas.<br>Little surprises.<br><em>Your next move.</em></h1><p>Explore Mill Creek with Scout. Follow the clues, change the plan, and find a smart way forward.</p><div class="launch-buttons">${saved?primary('Continue my adventure','resume'):primary('Let’s explore Mill Creek','start')}${saved?'<button class="text-button" data-command="new">Start a fresh adventure</button>':''}</div><span class="free-tag">FREE TO PLAY · FOUR STAGES · SIX ENDINGS</span><button class="text-button launch-book" data-command="book">Based on Jeremy Wenger’s land playbook ↗</button></div><div class="launch-art">${world({start:true})}${mascot('launch-scout')}<div class="hello-bubble">Hey, I’m Scout!<br><strong>Let’s find your way.</strong></div><span class="adventure-sticker">LET’S<br>EXPLORE!</span></div></section>`;}
function travelView(){const a=action(),e=encounters[a.id],done=state.done.includes(a.id);return `<section class="mission-page">${stepTrail(0)}<div class="mission-frame">${world()}<div class="mission-card"><span class="eyebrow">STAGE 0${a.phase+1} · ${stages[a.phase].name.toUpperCase()}</span><h1>${esc(e.task)}</h1>${guideLine(e.guide)}<div class="destination-label"><span>NEXT STOP</span><strong>${esc(e.place)}</strong></div>${primary(done?'Revisit this discovery':e.go,'arrive')}<p class="small-note">Exploring the map is free. You choose whether to spend on the next screen.</p></div></div></section>`;}
function decisionView(){const a=action(),e=encounters[a.id],reason=available(campaign,state,a);return `<section class="encounter-page">${stepTrail(1)}<button class="back-button" data-command="back-travel">← Back to the map</button><div class="encounter-banner"><span class="location-tag">${esc(e.place)}</span>${mascot('encounter-scout')}</div><div class="encounter-body"><span class="eyebrow">ONE QUESTION BEFORE YOUR NEXT COMMITMENT</span><h1>${esc(e.task)}</h1><blockquote>${esc(assumptions[a.id])}</blockquote><p>${esc(a.description)}</p><div class="cost-row"><span><small>GAME BUDGET</small><strong>${money(a.cost)}</strong></span><span><small>GAME TIME</small><strong>${a.days} ${a.days===1?'day':'days'}</strong></span></div>${reason?`<p class="notice">${esc(reason)}</p>${state.done.includes(a.id)?primary('See what we found','revisit'):primary('Guide me to an available move','guide')}`:primary(e.do,'commit')}<details class="data-panel"><summary>Why this move? Show the book lesson.</summary><p>${esc(campaign.book.chapters.find(c=>c.n===bookLenses[a.id]).body)}</p><button class="text-button" data-chapter="${bookLenses[a.id]}">Open chapter ${bookLenses[a.id]} note ↗</button></details></div></section>`;}
function resultView(){const a=outcome?.action??action(),e=encounters[a.id],earned=outcome?.before?stages.filter((_,i)=>!stageProgress(outcome.before,i).complete&&stageProgress(state,i).complete):[],events=outcome?.before?campaign.events.filter(ev=>state.events.includes(ev.id)&&!outcome.before.events.includes(ev.id)):[];const advanced=outcome?.before?campaign.routes.filter(r=>routePlan(campaign,outcome.before,r).remaining.length>routePlan(campaign,state,r).remaining.length):[];
  return `<section class="result-page">${stepTrail(2)}<div class="discovery-card"><div class="celebration" aria-hidden="true">${Array.from({length:8},(_,i)=>`<i style="--i:${i}">✦</i>`).join('')}</div><span class="eyebrow">${outcome?.before?'NEW DISCOVERY!':'FROM YOUR BACKPACK'}</span><h1>${esc(e.headline)}</h1><div class="big-reveal"><strong>${esc(e.big)}</strong><span>${esc(e.unit)}</span></div><p class="result-summary">${esc(e.summary)}</p>${earned.map(st=>`<div class="earned-badge"><span>✦</span><div><small>BOOK-STAGE BADGE EARNED</small><strong>${esc(st.reward)}</strong></div></div>`).join('')}${events.map(ev=>`<aside class="story-event"><span>! A TWIST IN THE STORY</span><strong>${esc(ev.title)}</strong><p>${esc(ev.lesson)}</p><details><summary>Read what happened</summary><p>${esc(ev.text)}</p></details></aside>`).join('')}${primary('Guide my next move','guide')}<details class="data-panel"><summary>Show the evidence & numbers</summary><p>${esc(a.result)}</p><dl class="fact-list"><div><dt>Investigation cost</dt><dd>${money(a.cost)}</dd></div><div><dt>Time spent</dt><dd>${a.days} days</dd></div><div><dt>Budget left</dt><dd>${money(state.cash)}</dd></div></dl>${advanced.length?`<h3>Your evidence advanced these routes</h3><ul>${advanced.map(r=>`<li>${esc(r.short)}: ${routePlan(campaign,state,r).ready?'ready to choose':routePlan(campaign,state,r).remaining.length+' game moves remain'}</li>`).join('')}</ul>`:''}</details><div class="discovery-lesson">${mascot()}<div><span>SCOUT’S FIELD NOTE</span><p>${esc(a.lesson)}</p><button class="text-button" data-chapter="${bookLenses[a.id]}">The book behind this move ↗</button></div></div></div></section>`;
}
function directionsView(){return `<section class="direction-page"><span class="eyebrow">SAME EVIDENCE. A DIFFERENT POSSIBILITY.</span><h1>Where shall we go from here?</h1><p class="page-intro">You keep everything you’ve discovered. Pick a direction, then explore one route at a time.</p><div class="direction-groups">${routeGroups.map(g=>`<button data-group="${g.id}" class="direction-choice"><span>${g.icon}</span><h2>${esc(g.name)}</h2><p>${esc(g.text)}</p><b>Explore this direction ➜</b></button>`).join('')}</div><div class="page-links"><button class="text-button" data-command="return">← Return to my adventure</button><button class="text-button" data-command="atlas">See how all six exits connect ↗</button></div></section>`;}
function routeView(){const r=route(),story=routeStories[r.id],plan=routePlan(campaign,state,r),g=routeGroups.find(x=>x.id===groupId)??routeGroups.find(x=>x.routes.includes(r.id)),index=g.routes.indexOf(r.id),extension=campaign.actions.find(a=>a.id==='extension');return `<section class="route-page"><button class="back-button" data-command="directions">← Choose a direction</button><div class="route-pagination"><span>${esc(g.name)} · ${index+1} of ${g.routes.length}</span>${g.routes.length>1?`<div><button data-route-cycle="-1" aria-label="Previous route">←</button><button data-route-cycle="1" aria-label="Next route">→</button></div>`:''}</div><div class="route-card"><div class="route-icon">${story.icon}</div><div><span class="eyebrow">${esc(r.kind.toUpperCase())}</span><h1>${esc(r.name)}</h1><div class="route-cause"><span>${esc(story.trigger)}</span><b aria-hidden="true">↓</b><strong>${esc(story.response)}</strong></div><p>${esc(r.summary)}</p><div class="tradeoff"><span>THE TRADEOFF</span><p>${esc(r.tradeoff)}</p></div><p class="route-readiness">${plan.ready?'✦ You have the game evidence to choose this ending.':plan.remaining.length+' guided moves to open this route.'}</p>${state.ending?primary('Rewind my last decision','replay'):plan.ready?primary('Choose this ending','finish'):plan.next?primary('Follow this route','follow'):primary('Find another direction','directions')}${!state.ending&&!plan.ready&&!plan.next&&!available(campaign,state,extension)?'<button class="text-button" data-action="extension">Explore the 15-day extension</button>':''}<details class="data-panel"><summary>Show the route’s evidence and costs</summary><p>${plan.remaining.length?money(plan.cost)+' and '+plan.days+' game days remain in this guided route.':'The game investigations for this route are complete.'} ${!plan.ready&&!plan.next?'The next move is blocked by your current budget, time, or move limit.':''}</p><ul class="evidence-list">${plan.ordered.map(a=>`<li><span>${state.done.includes(a.id)?'✓':'○'}</span><button data-action="${a.id}">${esc(a.short)}</button><small>${money(a.cost)} · ${a.days}d</small></li>`).join('')}</ul><p>${esc(r.next)}</p></details></div></div></section>`;}
function endingView(){const r=campaign.routes.find(x=>x.id===state.ending),story=routeStories[r.id],points=score(campaign,state);return `<section class="ending-page"><div class="ending-mascot">${mascot()}<span>✦ ADVENTURE COMPLETE ✦</span></div><span class="eyebrow">YOUR EXIT · ${esc(r.kind.toUpperCase())}</span><h1>${esc(r.name)}</h1><p class="page-intro">${esc(r.lesson)}</p><div class="badge-shelf">${stages.map((st,i)=>`<button data-stage="${i}" class="${stageProgress(state,i).complete?'earned':''}"><span>${stageProgress(state,i).complete?'✦':'○'}</span>${st.name}</button>`).join('')}</div><div class="next-chapter"><span class="eyebrow">TAKE THE NEXT CHAPTER WITH YOU</span><h2>You played one property.<br>Now learn the method for yours.</h2><p>Jeremy Wenger’s full book connects the questions, choices, and exits you just explored.</p><a class="button primary" href="${outbound('book','adventure_ending',r.id)}" target="_blank" rel="noopener">Get the complete book · $47 <span>↗</span></a><button class="button secondary" data-command="property">Have a real property? Bring in UPP <span>➜</span></button><small>Book first, or talk to the team whenever you’re ready.</small></div><details class="data-panel"><summary>My results, evidence & next step</summary><p><strong>${points}/100 decision score.</strong> Your score reflects evidence, control terms, team coordination, negotiated terms, supported routes, and the exit selected. It is not a forecast of profit or approval.</p><p>${money(state.cash)} game budget remains. ${state.deadline-state.day} days remain.</p><p>${esc(r.next)}</p><p>Stage badges record the work you explored. An early exit does not require every badge.</p><button class="text-button" data-command="export">Download my decision record ↓</button></details><div class="page-links"><button class="text-button" data-command="replay">↻ Try another ending</button><button class="text-button" data-command="new">Start a new adventure</button></div></section>`;}
function nextMove(){close();if(state.ending){show('ending');return;}const r=campaign.routes.find(x=>x.id===goal),plan=routePlan(campaign,state,r);if(plan.ready||!plan.next){routeId=goal;groupId=routeGroups.find(g=>g.routes.includes(goal)).id;show('route');if(!plan.ready)toast('Let’s compare your options. This route needs more time or budget.');return;}selected=plan.next.id;show('travel');}
function startNew(){state=initial(campaign);goal='smaller';outcome=null;save();close();nextMove();}
function goAction(id){const a=campaign.actions.find(x=>x.id===id);if(!a)return;close();selected=id;if(state.done.includes(id)){outcome={action:a,before:null};show('result');}else show('travel');}
function commit(){const a=action(),before=state;try{state=apply(campaign,state,a.id);}catch(e){toast(e.message);return;}save();outcome={action:a,before};chime(true);show('result');}
function finish(){if(state.ending){show('ending');return;}const r=route();goal=r.id;if(!routePlan(campaign,state,r).ready){save();nextMove();return;}try{state=apply(campaign,state,'exit:'+r.id);}catch(e){toast(e.message);return;}save();chime(true);show('ending');}
function changeDirection(){close();if(screen!=='directions'&&screen!=='route'){previousScreen=screen;previousSelected=selected;}show('directions');}
function replayEnding(){if(!state.ending){nextMove();return;}state=replay(campaign,state.history.slice(0,-1));save();close();previousScreen='travel';show('directions');toast('Your final decision is rewound. All your evidence and resources are still here.');}
function showBook(chapter){const entry=campaign.book.chapters.find(c=>c.n===chapter);modal(`<span class="eyebrow">THE BOOK BEHIND THE ADVENTURE</span><h2 id="modal-title">${entry?esc(entry.title):esc(campaign.book.title)}</h2><p>${entry?esc(entry.body):'You are playing the four stages of Jeremy Wenger’s land-decision framework. The complete book helps you bring those questions to your own property.'}</p>${entry?`<span class="chapter-tag">CHAPTER ${entry.n} · GAME FIELD NOTE</span>`:'<p>94 illustrated pages · PDF edition · $47</p>'}<a class="button primary" href="${outbound('book',entry?'chapter_'+entry.n:'adventure_menu',goal)}" target="_blank" rel="noopener">Get the complete book · $47 <span>↗</span></a><details class="data-panel"><summary>Explore the chapter notes</summary><div class="chapter-list">${campaign.book.chapters.map(c=>`<button data-chapter="${c.n}"><span>${String(c.n).padStart(2,'0')}</span>${esc(c.title)} <b>↗</b></button>`).join('')}</div></details><p class="small-note">These are short adapted game notes. The existing book checkout provides the complete book; unreleased paid campaigns are not included.</p>`);}
function showStage(index){const st=stages[index],p=stageProgress(state,index);modal(`<span class="eyebrow">BOOK STAGE 0${index+1}</span><h2 id="modal-title">${st.name}</h2>${guideLine(st.question)}<p>${esc(st.lesson)}</p><div class="stage-progress"><progress value="${p.done}" max="${p.total}" aria-label="Stage milestones"></progress><span>${p.complete?'✦ '+esc(st.reward):p.done+' of '+p.total+' milestones explored'}</span></div><button class="button primary" data-chapter="${st.chapter}">Read the book lesson <span>↗</span></button><button class="text-button" data-command="close">Back to the adventure</button>`);}
function showJournal(){modal(`<span class="eyebrow">YOUR ADVENTURE BACKPACK</span><h2 id="modal-title">${state.done.length?state.done.length+' discoveries collected.':'Every discovery starts with a question.'}</h2><p>Your evidence stays with you when you change direction.</p>${state.done.length?`<div class="journal-list">${state.done.map(id=>{const a=campaign.actions.find(x=>x.id===id);return `<details><summary><span>✓</span> ${esc(a.short)}</summary><p>${esc(a.result)}</p><button class="text-button" data-action="${a.id}">Revisit this discovery ↗</button></details>`;}).join('')}</div>`:'<p>Scout will help you make your first discovery.</p>'}<div class="modal-actions"><button class="button secondary" data-command="export">Download my record ↓</button><button class="text-button" data-command="moves">Choose a different investigation</button></div>`);}
function showMoves(){modal(`<span class="eyebrow">EXPLORE AT YOUR OWN PACE</span><h2 id="modal-title">Pick a different investigation.</h2><p>Your guided route is still saved. These moves let you explore beyond it.</p>${stages.slice(0,3).map((st,i)=>`<details class="data-panel"><summary>${st.name}</summary><div class="investigation-list">${campaign.actions.filter(a=>a.phase===i).map(a=>`<button data-action="${a.id}"><strong>${esc(a.short)}</strong><span>${state.done.includes(a.id)?'✓ In your backpack':available(campaign,state,a)||money(a.cost)+' · '+a.days+' days'}</span></button>`).join('')}</div></details>`).join('')}`);}
function showAtlas(){modal(`<span class="eyebrow">THE BIG PICTURE</span><h2 id="modal-title">One property. Six ways out.</h2><div class="atlas-root"><strong>The seller’s idea: 36 homes</strong><p>${state.done.includes('concept')?'Your concept screen ruled out the original sketch.':'An idea to investigate, not a confirmed yield.'}</p></div><div class="atlas-clues"><span>${state.done.includes('utilities')?'20-home utility ceiling':'Utilities unknown'}</span><span>${state.done.includes('land')?'5 acres reserved':'Land constraints unknown'}</span></div><div class="atlas-groups">${routeGroups.map(g=>`<section><h3>${esc(g.name)}</h3>${g.routes.map(id=>{const r=campaign.routes.find(x=>x.id===id),p=routePlan(campaign,state,r);return `<button data-route="${id}"><strong>${esc(r.short)}</strong><span>${p.ready?'✦ Ready to choose':p.remaining.length+' guided moves left'}</span></button>`;}).join('')}</section>`).join('')}</div><p class="small-note">Routes share discoveries. A new finding can open several possibilities at once.</p>`);}
function showProperty(){const id=state.ending??goal,r=campaign.routes.find(x=>x.id===id),st=routeStories[id];modal(`<span class="eyebrow">SCOUT HELPED WITH MILL CREEK. UPP CAN HELP WITH YOURS.</span><h2 id="modal-title">Let’s work through your real next move.</h2><p>You explored <strong>${esc(r.short.toLowerCase())}</strong>. Your property needs its own evidence.</p><div class="service-card"><span>A RELEVANT STARTING POINT</span><h3>${esc(st.service)}</h3><p>${esc(st.help)}</p></div><details class="data-panel"><summary>What should I bring?</summary><ul><li>Address or parcel number</li><li>Intended use and exit</li><li>Ownership or contract status and deadline</li><li>Available plans, surveys, and the biggest unknown</li></ul></details><a class="button primary" href="${outbound('contact','adventure_property',id)}" target="_blank" rel="noopener">Discuss my property with UPP <span>↗</span></a><p class="small-note">Opens UPP’s existing property intake. Your game record is not sent automatically.</p><button class="text-button" data-command="book">Still exploring? Start with the book ↗</button>`);}
function showMenu(){modal(`<span class="eyebrow">YOUR ADVENTURE</span><h2 id="modal-title">A few things for the road.</h2><div class="menu-list"><button data-command="atlas">Explore the exit map <span>↗</span></button><button data-command="moves">Choose an investigation <span>↗</span></button><button data-command="sound" aria-pressed="${sound}">Adventure sounds <strong>${sound?'On ♪':'Off'}</strong></button><button data-command="campaigns">Other adventures <span>↗</span></button><button data-command="export">Download my decision record <span>↓</span></button><button data-command="new">Start a new adventure <span>↻</span></button></div>`);}
function campaigns(){modal(`<span class="eyebrow">YOUR NEXT ADVENTURE</span><h2 id="modal-title">More land. More plot twists.</h2><p>Mill Creek is free to play now.</p>${primary(saved?'Continue Mill Creek':'Start Mill Creek',saved?'resume':'start')}<div class="coming"><h3>The Hospitality Pivot</h3><p>In development · Guest demand, wastewater, and a different way forward.</p><h3>The Contractor Yard</h3><p>In development · Access, customers, and phased infrastructure.</p></div><p class="small-note">These additional adventures are not on sale. The $47 purchase buys the book.</p>`);}
function newPrompt(){if(!saved){startNew();return;}modal(`<span class="eyebrow">A FRESH ADVENTURE</span><h2 id="modal-title">Ready for a new look at Mill Creek?</h2><p>This replaces the saved run on this device. You can download your current decision record first.</p>${primary('Start a fresh adventure','reset')}<button class="text-button" data-command="export">Download this run before I go ↓</button>`);}
function exportRecord(){const url=URL.createObjectURL(new Blob([brief(campaign,state)],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='mill-creek-decision-record.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your decision record is ready.');}
function camera(){const el=$('#world-camera');if(!el)return;pan.x=Math.max(-120*(zoom-1),Math.min(120*(zoom-1),pan.x));pan.y=Math.max(-90*(zoom-1),Math.min(90*(zoom-1),pan.y));el.style.transform=`translate(${pan.x}px,${pan.y}px) scale(${zoom})`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
  if(b.dataset.chapter){showBook(Number(b.dataset.chapter));return;}
  if(b.dataset.stage!==undefined){showStage(Number(b.dataset.stage));return;}
  if(b.dataset.action){goAction(b.dataset.action);return;}
  if(b.dataset.group){groupId=b.dataset.group;const g=routeGroups.find(x=>x.id===groupId);routeId=g.routes.includes(goal)?goal:g.routes[0];show('route');return;}
  if(b.dataset.route){close();routeId=b.dataset.route;groupId=routeGroups.find(g=>g.routes.includes(routeId)).id;show('route');return;}
  if(b.dataset.routeCycle){const g=routeGroups.find(x=>x.id===groupId),i=g.routes.indexOf(routeId);routeId=g.routes[(i+Number(b.dataset.routeCycle)+g.routes.length)%g.routes.length];show('route');return;}
  switch(b.dataset.command){
    case 'start':case 'new':newPrompt();break;
    case 'reset':startNew();break;
    case 'resume':case 'guide':nextMove();break;
    case 'arrive':if(state.done.includes(selected)){outcome={action:action(),before:null};show('result');}else{chime();show('decision');}break;
    case 'back-travel':show('travel');break;
    case 'commit':commit();break;
    case 'revisit':outcome={action:action(),before:null};show('result');break;
    case 'directions':changeDirection();break;
    case 'return':if(previousScreen==='launch'){show('launch');}else if(previousScreen==='ending'&&state.ending){show('ending');}else if(previousScreen==='result'&&outcome){show('result');}else if(state.ending){show('ending');}else if(['travel','decision'].includes(previousScreen)){selected=previousSelected;show(previousScreen);}else nextMove();break;
    case 'follow':goal=routeId;save();nextMove();break;
    case 'finish':finish();break;
    case 'replay':replayEnding();break;
    case 'book':showBook();break;
    case 'journal':showJournal();break;
    case 'moves':showMoves();break;
    case 'atlas':showAtlas();break;
    case 'property':showProperty();break;
    case 'menu':showMenu();break;
    case 'campaigns':campaigns();break;
    case 'sound':sound=!sound;chime(true);showMenu();break;
    case 'export':exportRecord();break;
    case 'close':close();break;
    case 'zoom-in':zoom=Math.min(1.7,zoom+.15);camera();break;
    case 'zoom-out':zoom=Math.max(1,zoom-.15);camera();break;
    case 'zoom-reset':zoom=1;pan={x:0,y:0};camera();break;
  }
});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close();});
document.addEventListener('pointerdown',e=>{const area=e.target.closest('.world-scene');if(!area||e.target.closest('button')||screen!=='travel')return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,px:pan.x,py:pan.y};area.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;pan={x:drag.px+e.clientX-drag.x,y:drag.py+e.clientY-drag.y};camera();});
document.addEventListener('pointerup',()=>drag=null);document.addEventListener('pointercancel',()=>drag=null);
render();
